//! Configuration revisions (§7.2).

use std::fmt;

use serde::{Deserialize, Serialize};

use crate::ValidationError;

/// Immutable revision identifier generated by the manager: `rev-` followed by at least six decimal digits.
///
/// Ordering compares the numeric part, so `rev-1000000` sorts after `rev-999999`.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(try_from = "String", into = "String")]
pub struct RevisionId {
    text: String,
    number: u64,
}

impl RevisionId {
    pub fn parse(text: &str) -> Result<Self, ValidationError> {
        let digits = text
            .strip_prefix("rev-")
            .filter(|d| d.len() >= 6 && d.len() <= 18 && d.bytes().all(|b| b.is_ascii_digit()))
            .ok_or_else(|| ValidationError::new("", format!("invalid revision {text:?}, expected rev-NNNNNN")))?;
        let number = digits.parse().map_err(|_| ValidationError::new("", "revision number out of range"))?;
        Ok(Self { text: text.to_owned(), number })
    }

    pub fn from_number(number: u64) -> Self {
        Self { text: format!("rev-{number:06}"), number }
    }

    pub fn number(&self) -> u64 {
        self.number
    }

    pub fn as_str(&self) -> &str {
        &self.text
    }
}

impl PartialOrd for RevisionId {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for RevisionId {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.number.cmp(&other.number)
    }
}

impl TryFrom<String> for RevisionId {
    type Error = ValidationError;
    fn try_from(value: String) -> Result<Self, Self::Error> {
        Self::parse(&value)
    }
}

impl From<RevisionId> for String {
    fn from(value: RevisionId) -> Self {
        value.text
    }
}

impl fmt::Display for RevisionId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.text)
    }
}

/// Metadata attached to every published node snapshot.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct RevisionMeta {
    pub revision: RevisionId,
    pub schema_version: u32,
    /// SHA-256 (hex) of the canonical JSON of the node config snapshot.
    pub config_digest: String,
    /// RFC 3339 UTC timestamp.
    pub generated_at: String,
}

/// The six revision pointers a node tracks (§7.2). Each advances independently.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct RevisionPointers {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub desired_revision: Option<RevisionId>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub received_revision: Option<RevisionId>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub validated_revision: Option<RevisionId>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub applied_revision: Option<RevisionId>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub observed_revision: Option<RevisionId>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_successful_revision: Option<RevisionId>,
}

impl schemars::JsonSchema for RevisionId {
    fn schema_name() -> std::borrow::Cow<'static, str> {
        "RevisionId".into()
    }

    fn json_schema(_: &mut schemars::SchemaGenerator) -> schemars::Schema {
        schemars::json_schema!({"type": "string", "pattern": "^rev-[0-9]{6,18}$", "description": "Immutable revision id"})
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_and_order() {
        let a = RevisionId::parse("rev-000042").unwrap();
        let b = RevisionId::parse("rev-1000000").unwrap();
        assert!(a < b);
        assert_eq!(a.number(), 42);
        assert_eq!(RevisionId::from_number(43).as_str(), "rev-000043");
        assert!(RevisionId::parse("rev-42").is_err());
        assert!(RevisionId::parse("r-000042").is_err());
        let json = serde_json::to_string(&a).unwrap();
        assert_eq!(json, "\"rev-000042\"");
        let back: RevisionId = serde_json::from_str(&json).unwrap();
        assert_eq!(back, a);
    }
}
